    def xǁKnowledgeGraphExporterǁexport__mutmut_orig(
        self,
        format: ExportFormat,
        output_path: Optional[Union[str, Path]] = None,
    ) -> ExportResult:
        """Export to specified format.

        Args:
            format: Target export format
            output_path: Optional output file path

        Returns:
            ExportResult with status and content/path
        """
        output_path = Path(output_path) if output_path else None

        try:
            if format == ExportFormat.JSON:
                content = self._export_json()
            elif format == ExportFormat.GRAPHML:
                content = self._export_graphml()
            elif format == ExportFormat.DOT:
                content = self._export_dot()
            elif format == ExportFormat.SQLITE:
                if not output_path:
                    return ExportResult(
                        format=format,
                        output_path=None,
                        content=None,
                        success=False,
                        error="SQLite export requires output_path",
                    )
                self._export_sqlite(output_path)
                return ExportResult(
                    format=format,
                    output_path=output_path,
                    content=None,
                    success=True,
                )
            elif format == ExportFormat.MARKDOWN:
                content = self._export_markdown()
            else:
                return ExportResult(
                    format=format,
                    output_path=output_path,
                    content=None,
                    success=False,
                    error=f"Unsupported format: {format}",
                )

            if output_path:
                output_path.write_text(content, encoding="utf-8")

            return ExportResult(
                format=format,
                output_path=output_path,
                content=content if not output_path else None,
                success=True,
            )

        except Exception as e:
            logger.debug(f"Exception: {e}")
            logger.debug("Exception caught, returning", exc_info=True)
            return ExportResult(
                format=format,
                output_path=output_path,
                content=None,
                success=False,
                error=str(e),
            )

